detailed.py:
"""Explicit, selected-snapshot detailed validation; never runs on ordinary cases."""
from __future__ import annotations
import math
import time
import pandapower as pp
from pandapower.powerflow import LoadflowNotConverged
from mvgrid.paths import NOVI_SAD_MODEL_DIR


def detailed_check(result, steps):
    """Replay exact block dispatch into detailed member loads; hubs use source MV bus."""
    net=pp.from_json(str(NOVI_SAD_MODEL_DIR/'ppnet_novi_sad.json'))
    if result.get('capacity_alignment'):
        from .rebalance import rebalance_sources
        from .capacity_alignment import align_delivery_capacity
        excluded=result['capacity_alignment'].get('excluded_sources',[])
        rebalance_sources(net,excluded)
        align_delivery_capacity(net, result['capacity_alignment']['estimate'],excluded_sources=excluded)
    indices={str(row.synthetic_id):int(i) for i,row in net.load.iterrows()}
    original=net.load.p_mw.copy()
    net.load.loc[:,['p_mw','q_mvar']]=0.0
    blocks={b['id']:b for b in result['blocks']}
    active_sources={b['source_id'] for b in result['blocks']}
    for index,row in net.ext_grid.iterrows():
        if str(net.bus.at[int(row.bus),'zone']) not in active_sources:
            net.ext_grid.at[index,'in_service']=False
    hub_loads={}
    for b in result['blocks']:
        if b.get('kind')=='public_hub':
            candidates=net.load[net.load.primary_station_id==b['source_id']]
            if candidates.empty: raise ValueError('No detailed source mapping')
            # Explicit proxy connection: source LV side of highest-voltage transformer.
            station_trafos=net.trafo[net.trafo.station_id==b.get('delivery_id',b['source_id'])]
            trafo=station_trafos.sort_values('vn_hv_kv',ascending=False).iloc[0]
            hub_loads[b['id']]=pp.create_load(net,int(trafo.lv_bus),p_mw=0,q_mvar=0,name=b['id'])
    output=[]
    for step in steps:
        interval=result['intervals'][step]
        for snapshot in interval['blocks']:
            block=blocks[snapshot['id']]
            members=[indices[x] for x in block['member_ids']]
            if members:
                weights=original.loc[members]/original.loc[members].sum()
                for index,weight in weights.items():
                    p=snapshot['total_kw']/1000*weight
                    net.load.loc[index,['p_mw','q_mvar']]=[p,p*math.tan(math.acos(.97))]
            else:
                p=snapshot['total_kw']/1000
                net.load.loc[hub_loads[block['id']],['p_mw','q_mvar']]=[p,p*math.tan(math.acos(.97))]
        started=time.perf_counter()
        try:
            pp.runpp(net,numba=False,max_iteration=40)
            detailed=dict(converged=True,min_voltage_pu=float(net.res_bus.vm_pu.min()),max_line_loading_percent=float(net.res_line.loading_percent.max()),max_transformer_loading_percent=float(net.res_trafo.loading_percent.max()),losses_kw=float((net.res_line.pl_mw.sum()+net.res_trafo.pl_mw.sum())*1000))
        except LoadflowNotConverged:
            detailed=dict(converged=False)
        delta={key:detailed[key]-interval[key] for key in ('min_voltage_pu','max_line_loading_percent','max_transformer_loading_percent','losses_kw') if detailed.get(key) is not None and interval.get(key) is not None}
        output.append(dict(step=step,detailed=detailed,reduced={k:interval.get(k) for k in detailed},detailed_minus_reduced=delta,runtime_seconds=time.perf_counter()-started))
    return dict(snapshots=output,assumptions=['Block charging distributed by member baseline demand shares.','Dedicated illustrative hubs attached to delivery transformer LV bus; excluded source loads zeroed.','Selected snapshots only; no full-year electrical feasibility claim.'])

districts.py:
"""Explicit aggregate district budgets, not physical MV/LV transformer ratings."""
from .schema import DistrictCapacity


def district_id(block):
    return str(block.get('delivery_station_id',block.get('delivery_id',block.get('source_id',block.get('id')))))


def resolve_districts(blocks, config=None):
    cfg=DistrictCapacity.model_validate(config or {})
    groups={}
    for block in blocks:
        groups.setdefault(district_id(block),[]).append(block)
    unknown=set(cfg.overrides)-set(groups)
    if unknown: raise ValueError('Unknown district IDs: '+', '.join(sorted(unknown)))
    factor={'low':.8,'central':1.,'high':1.2}[cfg.scenario]
    result=[]
    for key,members in sorted(groups.items()):
        override=cfg.overrides.get(key)
        central=(float(members[0].get('delivery_capacity_kw',members[0]['source_capacity_kw']))*members[0].get('district_planning_factor',.8))
        provenance=members[0].get('capacity_provenance','Engineering estimate: delivery station MVA × 0.97 × 0.8; not an EDS district operating limit or physical MV/LV rating.')
        if override: central=override.capacity_kw;provenance=override.provenance
        result.append(dict(id=key,source_id=members[0]['source_id'],block_ids=[b['id'] for b in members],capacity_kw=central*factor,central_capacity_kw=central,scenario=cfg.scenario,scenario_factor=factor,provenance=provenance,uncertainty='Low/central/high factors 0.8/1/1.2 are engineering uncertainty assumptions, including for overrides.'))
    return result


def validate_district_mix(blocks, mix):
    unknown=set(mix or {})-{district_id(b) for b in blocks}
    if unknown: raise ValueError('Unknown district IDs in fleet.district_mix: '+', '.join(sorted(unknown)))


def validate_district_locations(blocks, fleet):
    if not fleet.get('district_mix') or fleet.get('location_mix',{}).get('public',.1) <= 0:
        return
    hubs={district_id(b) for b in blocks if b.get('kind')=='public_hub'}
    missing=set(fleet['district_mix'])-hubs
    if missing:
        raise ValueError('No public charging hub in '+', '.join(sorted(missing))+'. Set public charging share to zero or choose districts with public hubs.')

mcp_server.py:
"""Local typed MCP interface; tools orchestrate experiments, never arbitrary code."""
from __future__ import annotations
from typing import Any
from mcp.server import MCPServer
from mcp.types import ToolAnnotations
from .service import Service
from functools import wraps
from mcp.server.mcpserver.exceptions import ToolError

def tool_errors(fn):
    @wraps(fn)
    def wrapped(*args, **kwargs):
        try:
            return fn(*args, **kwargs)
        except (ValueError, FileNotFoundError, KeyError) as error:
            raise ToolError(str(error)) from error
    return wrapped

server = MCPServer("ev_playground_mcp", instructions="Synthetic EV hypothesis playground. Validate and freeze experiments before running. Distinguish incomplete, rejected and completed evidence. Detailed network checks are optional.")
READ = ToolAnnotations(readOnlyHint=True, destructiveHint=False, openWorldHint=False)
WRITE = ToolAnnotations(readOnlyHint=False, destructiveHint=False, openWorldHint=False)

@server.tool(annotations=READ, structured_output=True)
@tool_errors
def ev_get_catalog() -> dict[str, Any]:
    """Discover experiment JSON schema, supported strategies, metrics and a valid example."""
    return Service().catalog()

@server.tool(annotations=READ, structured_output=True)
@tool_errors
def ev_list_experiments() -> dict[str, Any]:
    """List saved experiment revisions and local runs."""
    s = Service()
    return {"experiments": s.list_experiments(), "runs": s.list_runs()}

@server.tool(annotations=READ, structured_output=True)
@tool_errors
def ev_validate_experiment(definition: dict) -> dict[str, Any]:
    """Validate typed JSON and expand a bounded case matrix without executing it."""
    return Service().validate_experiment(definition)

@server.tool(annotations=WRITE, structured_output=True)
@tool_errors
def ev_save_experiment(definition: dict) -> dict[str, Any]:
    """Save a validated immutable definition; identical definitions reuse the same ID."""
    return Service().save_experiment(definition)

@server.tool(annotations=WRITE, structured_output=True)
@tool_errors
def ev_add_cases(experiment_id: str, patch: dict) -> dict[str, Any]:
    """Create a revision by replacing supplied top-level fields, including seeds or fleet_sizes."""
    return Service().add_cases(experiment_id, patch)

@server.tool(annotations=WRITE, structured_output=True)
@tool_errors
def ev_start_run(experiment_id: str, resume_run_id: str | None = None) -> dict[str, Any]:
    """Start one background worker or resume a matching interrupted run; returns a run ID promptly."""
    return Service().start_run(experiment_id, resume_run_id)

@server.tool(annotations=READ, structured_output=True)
@tool_errors
def ev_get_run(run_id: str) -> dict[str, Any]:
    """Get progress, coverage, verdict and actionable errors for a run."""
    return Service().get_run(run_id)

@server.tool(annotations=WRITE, structured_output=True)
@tool_errors
def ev_cancel_run(run_id: str) -> dict[str, Any]:
    """Request cancellation at the next interval; completed cases remain resumable."""
    return Service().cancel_run(run_id)

@server.tool(annotations=READ, structured_output=True)
@tool_errors
def ev_get_results(run_id: str, case_id: str | None = None, include_intervals: bool = False) -> dict[str, Any]:
    """Get metrics and assertion counterexamples; opt into detailed interval/block snapshots for one case."""
    if include_intervals and not case_id:
        raise ValueError("Provide case_id when requesting detailed interval data.")
    result = Service().get_results(run_id, case_id)
    if not include_intervals:
        result["cases"] = [{k:v for k,v in c.items() if k not in ("intervals", "sessions", "blocks", "hierarchy_nodes", "hierarchy_edges")} for c in result["cases"]]
    return result

@server.tool(annotations=READ, structured_output=True)
@tool_errors
def ev_compare_runs(run_ids: list[str]) -> dict[str, Any]:
    """Compare saved metrics and expose differences that prevent a controlled paired comparison."""
    return Service().compare_runs(run_ids)

from .strategy_workflow import register_strategy_tools
register_strategy_tools(server, READ, WRITE, tool_errors)


@server.tool(annotations=READ, structured_output=True)
@tool_errors
def ev_get_rl_catalog() -> dict[str, Any]:
    """List trained immutable RL models, training jobs and default settings."""
    from .rl_service import RLService
    return RLService().catalog()


@server.tool(annotations=WRITE, structured_output=True)
@tool_errors
def ev_train_rl(experiment_id: str, config: dict) -> dict[str, Any]:
    """Train a fresh binary policy on randomized days; returns a bounded background job."""
    from .rl_service import RLService
    return RLService().start(experiment_id, config)


@server.tool(annotations=READ, structured_output=True)
@tool_errors
def ev_get_rl_job(job_id: str) -> dict[str, Any]:
    """Read training progress and measured episode history."""
    from .rl_service import RLService
    return RLService().get_job(job_id)


@server.tool(annotations=WRITE, structured_output=True)
@tool_errors
def ev_cancel_rl(job_id: str) -> dict[str, Any]:
    """Request cancellation; incomplete training never publishes a selectable model."""
    from .rl_service import RLService
    return RLService().cancel(job_id)


def main():
    server.run(transport="stdio")

if __name__ == "__main__":
    main()

rebalance.py:
"""Reassign removed 20-kV source feeder branches without dropping city demand."""
import networkx as nx


def rebalance_sources(net, excluded_sources):
    excluded=set(excluded_sources)
    if not excluded:
        return []
    stations=net.trafo.set_index('station_id',drop=False)
    if any(float(stations.loc[s,'vn_lv_kv']) != 20 for s in excluded):
        raise ValueError('Source rebalancing currently supports 20-kV source removal only')
    targets=sorted(str(s) for s,r in stations.iterrows() if r.vn_lv_kv==20 and s not in excluded)
    if not targets:
        raise ValueError('At least one 20-kV source must remain')
    graph=nx.Graph()
    for index,line in net.line.iterrows():
        graph.add_edge(int(line.from_bus),int(line.to_bus),index=int(index))
    demand={s:float(net.load.loc[net.load.primary_station_id==s,'p_mw'].sum()) for s in targets}
    branches=[]
    for source in sorted(excluded):
        root=int(stations.loc[source,'lv_bus'])
        tree=graph.subgraph(nx.node_connected_component(graph,root)).copy()
        edges=[(neighbor,tree[root][neighbor]['index']) for neighbor in tree.neighbors(root)]
        tree.remove_node(root)
        source_loads=net.load[net.load.primary_station_id==source]
        for neighbor,index in edges:
            buses=nx.node_connected_component(tree,neighbor)
            members=list(source_loads.index[source_loads.bus.isin(buses)])
            if members:
                branches.append((float(net.load.loc[members,'p_mw'].sum()),source,root,index,members))
        direct=list(source_loads.index[source_loads.bus==root])
        if direct:
            branches.append((float(net.load.loc[direct,'p_mw'].sum()),source,root,None,direct))
    records=[]
    for mw,source,root,index,members in sorted(branches,key=lambda r:(-r[0],r[1],-1 if r[3] is None else r[3])):
        target=min(targets,key=lambda s:((demand[s]+mw)/float(stations.loc[s,'sn_mva']),s))
        target_root=int(stations.loc[target,'lv_bus'])
        if index is None:
            net.load.loc[members,'bus']=target_root
        else:
            endpoint='from_bus' if int(net.line.at[index,'from_bus'])==root else 'to_bus'
            net.line.at[index,endpoint]=target_root
        net.load.loc[members,['primary_station_id','delivery_station_id']]=[target,target]
        demand[target]+=mw
        records.append(dict(original_source=source,source_id=target,reference_line_index=index,
                            demand_mw=mw,member_ids=[str(net.load.at[i,'synthetic_id']) for i in members]))
    if net.load.primary_station_id.isin(excluded).any():
        raise ValueError('Source reassignment did not cover every removed-source load')
    net.trafo.loc[net.trafo.station_id.isin(excluded),'in_service']=False
    for i,row in net.ext_grid.iterrows():
        if str(net.bus.at[int(row.bus),'zone']) in excluded:
            net.ext_grid.at[i,'in_service']=False
    return records

rl.py:
"""Centralized binary charging policy and auditable episodic policy-gradient learning.

One shared neural actor observes city/grid context plus each connected session.
Its joint action is a vector of Bernoulli switches, not a power modulation.
Only NumPy is required. This is REINFORCE, not PPO or a pretrained optimal policy.
"""
from __future__ import annotations

import math
import numpy as np
from .capacity_layers import capacity_layers, ev_stage_fraction
from .districts import district_id
from .schema import RewardWeights

FEATURE_VERSION = 1
FEATURES = ['remaining_fraction', 'hours_left', 'required_fraction', 'slack',
            'baseline_ratio', 'district_ratio', 'source_ratio', 'block_ratio',
            'stage_headroom', 'clock_sin', 'clock_cos', 'previous_on',
            'connected_power_ratio', 'urgency_pressure', 'energy_headroom', 'charger_ratio']


def current_baseline(sim):
    t = sim.index
    return {b['id']:float(sim.case['block_demand_kw'][b['id']][t])
            if sim.case.get('block_demand_kw') else sim.demand[t]*b['base_weight'] for b in sim.blocks}


def features(sim, previous=None, energy_used=0., energy_limit=None):
    """Current observations only; future demand and arrivals are never actor inputs."""
    previous = previous or {}
    connected = sorted((s for s in sim.observation()['sessions'] if s['remaining_kwh'] > 1e-8), key=lambda s:str(s['id']))
    baseline = current_baseline(sim)
    total_capacity = max(sum(d['capacity_kw'] for d in sim.resolved_districts), 1.)
    total = sum(baseline.values())
    district_load = {d['id']:sum(baseline[b] for b in d['block_ids']) for d in sim.resolved_districts}
    source_load = {}
    for b in sim.blocks:
        source_load[b['source_id']] = source_load.get(b['source_id'], 0.) + baseline[b['id']]
    stages = capacity_layers(sim.net, sim.blocks, baseline, {b['id']:0. for b in sim.blocks}, sim.case.get('network_capacity'))
    headroom = min((r['headroom_kw']/r['capacity_kw'] for r in stages), default=1.)
    connected_power = sum(s['charger_kw'] for s in connected)/total_capacity
    phase = 2*math.pi*(sim.index*sim.dt % 24)/24
    rows = []
    for s in connected:
        b = sim.by_id[s['block_id']]
        d = district_id(b)
        hours = (s['departure_step']-sim.index)*sim.dt
        need = s['remaining_kwh']/(s['charger_kw']*s.get('efficiency', .9))
        ratio = district_load[d]/sim.district_by_id[d]['capacity_kw']
        rows.append([s['remaining_kwh']/max(s['energy_kwh'],1e-9), hours/24,
                     need/max(hours,sim.dt), (hours-need)/24, total/total_capacity,
                     ratio, source_load[b['source_id']]/max(b['source_capacity_kw'],1.),
                     baseline[b['id']]/max(b['capacity_kw'],1.), headroom,
                     math.sin(phase),math.cos(phase),float(previous.get(s['id'],False)),
                     connected_power, ratio*need/max(hours,sim.dt),
                     (energy_limit-energy_used)/energy_limit if energy_limit else 1.,
                     s['charger_kw']/max(b['capacity_kw'],1.)])
    return connected, np.clip(np.asarray(rows,dtype=float).reshape(-1,len(FEATURES)), -10, 10)


class BinaryPolicy:
    def __init__(self, seed=0, weights=None):
        rng = np.random.default_rng(seed)
        self.weights = {k:np.asarray(v,dtype=float) for k,v in weights.items()} if weights else {
            'w1':rng.normal(0,.15,(len(FEATURES),24)), 'b1':np.zeros(24),
            'w2':rng.normal(0,.15,24), 'b2':np.zeros(1)}
        shapes = {'w1':(len(FEATURES),24),'b1':(24,),'w2':(24,),'b2':(1,)}
        if set(self.weights)!=set(shapes) or any(self.weights[k].shape!=v or not np.isfinite(self.weights[k]).all() for k,v in shapes.items()):
            raise ValueError('Invalid policy weights')
        self.baseline = None

    def probabilities(self, x):
        h = np.tanh(x@self.weights['w1']+self.weights['b1'])
        logits = np.clip(h@self.weights['w2']+self.weights['b2'][0],-20,20)
        return 1/(1+np.exp(-logits))

    def predict(self, x, rng=None):
        p = self.probabilities(x)
        return ((rng.random(len(p)) < p) if rng is not None else (p >= .5)).astype(int), p

    def to_dict(self):
        return {'algorithm':'centralized-bernoulli-reinforce', 'feature_version':FEATURE_VERSION,
                'features':FEATURES, 'weights':{k:v.tolist() for k,v in self.weights.items()}}

    @classmethod
    def from_dict(cls, data):
        if data.get('feature_version') != FEATURE_VERSION or data.get('features') != FEATURES or data.get('algorithm')!='centralized-bernoulli-reinforce':
            raise ValueError('Unsupported policy feature/algorithm version')
        return cls(weights=data['weights'])

    def update(self, trajectory, learning_rate=.01, gamma=.99):
        """REINFORCE with previous-episode time baselines and bounded gradient norm.

        Trajectory entries contain x/actions/probabilities/reward. The score is for
        requested switches, including shielded proposals; no gradient is fabricated
        from the executed action. Running baselines never use this episode first.
        """
        if not trajectory: return 0.
        returns = np.zeros(len(trajectory)); running = 0.
        for t in range(len(trajectory)-1,-1,-1):
            running = float(trajectory[t]['reward'])+gamma*running
            returns[t] = running
        baseline = np.zeros(len(returns))
        if self.baseline is not None:
            n = min(len(returns),len(self.baseline)); baseline[:n] = self.baseline[:n]
        advantage = (returns-baseline)/max(float(np.std(returns-baseline)),1.)
        gradients = {k:np.zeros_like(v) for k,v in self.weights.items()}
        for item, adv in zip(trajectory,advantage):
            x = item['x']; residual = (item['actions']-item['probabilities'])*adv
            h = np.tanh(x@self.weights['w1']+self.weights['b1'])
            gradients['w2'] += h.T@residual
            gradients['b2'][0] += residual.sum()
            dh = residual[:,None]*self.weights['w2'][None,:]*(1-h*h)
            gradients['w1'] += x.T@dh
            gradients['b1'] += dh.sum(axis=0)
        gradients = {k:v/len(trajectory) for k,v in gradients.items()}
        norm = math.sqrt(sum(float(np.sum(v*v)) for v in gradients.values()))
        for k,g in gradients.items(): self.weights[k] += learning_rate*g*min(1.,10/max(norm,1e-12))
        self.baseline = .9*baseline+.1*returns
        if any(not np.isfinite(v).all() for v in self.weights.values()): raise ValueError('Training produced nonfinite weights')
        return norm


def shield_actions(sim, actions, probabilities=None, energy_remaining=None):
    """Binary admission by urgency under shared block, source, district and stage budgets.

    AC checks and additional binary removals happen in Simulator.step. An unsafe
    baseline remains visible: turning off all chargers cannot fix baseline demand.
    """
    baseline = current_baseline(sim)
    factor = sim.case.get('limits',{}).get('max_loading_percent',100)/100
    block_left = {b['id']:max(0.,b['capacity_kw']*factor-baseline[b['id']]) for b in sim.blocks}
    source_left = {}
    district_left = {d['id']:d['capacity_kw']-sum(baseline[b] for b in d['block_ids']) for d in sim.resolved_districts}
    for b in sim.blocks:
        source_left.setdefault(b['source_id'],b['source_capacity_kw']*factor)
        source_left[b['source_id']] -= baseline[b['id']]
    stages = capacity_layers(sim.net,sim.blocks,baseline,{b['id']:0. for b in sim.blocks},sim.case.get('network_capacity'))
    stage_left = {r['id']:r['headroom_kw'] for r in stages}
    remaining_kw = max(0.,energy_remaining/sim.dt-sum(baseline.values())) if energy_remaining is not None else math.inf
    result = {}
    sessions = sim.observation()['sessions']
    def priority(s):
        laxity = (s['departure_step']-sim.index)*sim.dt-s['remaining_kwh']/(s['charger_kw']*s.get('efficiency',.9))
        return laxity,-(probabilities or {}).get(s['id'],0),str(s['id'])
    for s in sorted(sessions,key=priority):
        power = float(actions.get(s['id'],0.))
        b = sim.by_id[s['block_id']]; d = district_id(b)
        allowed = min(block_left[b['id']],max(0.,source_left[b['source_id']]),max(0.,district_left[d]),remaining_kw)
        for stage,left in stage_left.items():
            share = ev_stage_fraction(stage,b,sim.case.get('network_capacity'))
            if share: allowed = min(allowed,max(0.,left)/share)
        power = power if power <= allowed+1e-9 else 0.
        result[s['id']] = power
        block_left[b['id']] -= power; source_left[b['source_id']] -= power; district_left[d] -= power; remaining_kw -= power
        for stage in stage_left: stage_left[stage] -= power*ev_stage_fraction(stage,b,sim.case.get('network_capacity'))
    return result


def reward_signal(interval, sessions, dt, weights=None, switches=0, interventions=0,
                  energy_before=0., energy_limit=None, energy_scale=None, fleet_scale=None):
    weights = RewardWeights.model_validate(weights or {}).model_dump()
    scale = max(float(energy_scale if energy_scale is not None else sum(s['energy_kwh'] for s in sessions)),1.)
    count = max(int(fleet_scale if fleet_scale is not None else len(sessions)),1)
    # Deduplicate upstream violations repeated once for each affected demand block.
    unique = {(v['kind'],v.get('asset_type'),v.get('asset_id')):v for v in interval['violations'] if v['kind']!='daily_energy_exceeded'}
    severity = 0.
    for v in unique.values():
        value,limit = v.get('value'),v.get('limit')
        if value is not None and limit: severity = max(severity,abs(value-limit)/abs(limit))
    departure_shortfall = sum(s['remaining_kwh'] for s in sessions if s['departure_step']==interval['step']+1)
    efficiency = {s['id']:s.get('efficiency',.9) for s in sessions}
    delivered = sum(v['power_kw']*dt*efficiency[v['id']]
                    for b in interval['blocks'] for v in b['vehicles'] if v['power_kw']>0)
    after = energy_before+interval['total_kw']*dt
    excess = max(0.,after-energy_limit)-max(0.,energy_before-energy_limit) if energy_limit else 0.
    capacity = sum(d['capacity_kw'] for d in interval['districts']) or 1.
    raw = {'delivery':delivered/scale,'shortfall':-departure_shortfall/scale,
           'capacity':-(1+severity) if unique else 0.,
           'energy':-(1+excess/energy_limit) if energy_limit and after>energy_limit+1e-9 else 0.,
           'switching':-switches/count, 'peak':-(interval['total_kw']/capacity)**2,
           'intervention':-interventions/count}
    components = {k:float(raw[k]*weights[k]) for k in raw}
    return {'reward':sum(components.values()),'components':components,'energy_excess_kwh':excess}


class RLController:
    def __init__(self, policy, config=None, seed=None, training=False):
        self.policy = policy; self.config = config or {}; self.training = training
        self.rng = np.random.default_rng(seed) if training else None
        self.previous = {}; self.energy_used = 0.; self.day = None; self.trajectory = []

    def actions(self, sim):
        day = int(sim.index*sim.dt//24)
        if self.day != day: self.day = day; self.energy_used = 0.
        limit = self.config.get('daily_energy_limit_kwh')
        sessions,x = features(sim,self.previous,self.energy_used,limit)
        actions,p = self.policy.predict(x,self.rng)
        requested = {s['id']:min(s['charger_kw'],s['remaining_kwh']/(sim.dt*s.get('efficiency',.9)))*int(a) for s,a in zip(sessions,actions)}
        proposed = shield_actions(sim,requested,dict(zip((s['id'] for s in sessions),p)),limit-self.energy_used if limit else None) if self.config.get('safety_shield',True) else requested
        self.pending = {'x':x,'actions':actions,'probabilities':p,'requested':requested}
        return proposed

    def observe(self, sim, interval):
        actual = {v['id']:v['power_kw']>1e-9 for b in interval['blocks'] for v in b['vehicles']}
        requested = self.pending['requested']
        interval['requested_ev_kw'] = sum(requested.values())
        interval['curtailed_ev_kw'] = max(0.,sum(requested.values())-interval['ev_kw'])
        # Arrival is not a switch from a previous controlled state; departure likewise.
        switches = sum(on != self.previous[k] for k,on in actual.items() if k in self.previous)
        interventions = sum(p>1e-9 and not actual.get(k,False) for k,p in requested.items())
        reward = reward_signal(interval,sim.sessions,sim.dt,self.config.get('reward'),switches,interventions,self.energy_used,self.config.get('daily_energy_limit_kwh'))
        interval['rl'] = {**reward,'requested_on':sum(p>1e-9 for p in requested.values()),
                          'executed_on':sum(actual.values()),'switches':switches,'interventions':interventions,
                          'daily_energy_kwh':self.energy_used+interval['total_kw']*sim.dt}
        self.energy_used += interval['total_kw']*sim.dt
        self.previous = actual
        if self.training: self.trajectory.append({**self.pending,'reward':reward['reward']})
        return interval['rl']

schema.py:
"""Strict input schema for the EV hypothesis playground."""

from __future__ import annotations

from collections.abc import Mapping
from typing import Annotated, Literal

import yaml
from pydantic import BaseModel, ConfigDict, Field, TypeAdapter, field_validator, model_validator
from .strategies import StrategyOptions


class StrictModel(BaseModel):
    model_config = ConfigDict(extra="forbid", frozen=True)


FinitePositive = Annotated[float, Field(gt=0, allow_inf_nan=False)]
FiniteFraction = Annotated[float, Field(ge=0, le=1, allow_inf_nan=False)]


class CompositionConfig(StrictModel):
    mode: Literal["preserve_city", "preserve_energy"] = "preserve_city"
    residential: FiniteFraction | None = None
    commercial: FiniteFraction | None = None
    industrial: FiniteFraction | None = None

    @model_validator(mode="after")
    def weights_sum_to_one(self) -> "CompositionConfig":
        weights = (self.residential, self.commercial, self.industrial)
        if any(value is not None for value in weights):
            if any(value is None for value in weights) or abs(sum(weights) - 1.0) > 1e-9:
                raise ValueError("composition weights must all be supplied and sum to 1")
        return self


class DemandConfig(StrictModel):
    scope: Literal["city_total", "active_sources"] = "city_total"
    monthly_energy: FinitePositive = 95_636.0
    unit: Literal["kWh", "MWh"] = "MWh"
    month: Annotated[int, Field(ge=1, le=12)] = 1
    days_per_month: Annotated[int, Field(ge=1, le=31)] = 30
    days: Annotated[int, Field(ge=1, le=31)] = 1
    annual_growth_rate: FiniteFraction = 0.03
    years_ahead: Annotated[int, Field(ge=0, le=100)] = 0
    scenario: Literal["base", "worst_case"] = "base"
    variation: Literal["base", "lower", "upper"] = "base"
    composition: CompositionConfig = Field(default_factory=CompositionConfig)
    randomize: bool = False
    daily_scale_min: Annotated[float, Field(gt=0, le=3, allow_inf_nan=False)] = 0.8
    daily_scale_max: Annotated[float, Field(gt=0, le=3, allow_inf_nan=False)] = 1.2
    shape_noise: Annotated[float, Field(ge=0, le=0.5, allow_inf_nan=False)] = 0.1

    @model_validator(mode='after')
    def ordered_scales(self):
        if self.daily_scale_min > self.daily_scale_max:
            raise ValueError('daily_scale_min must not exceed daily_scale_max')
        return self


class LocationMix(StrictModel):
    residential: FiniteFraction = 0.7
    workplace: FiniteFraction = 0.2
    public: FiniteFraction = 0.1

    @model_validator(mode="after")
    def weights_sum_to_one(self) -> "LocationMix":
        if abs(self.residential + self.workplace + self.public - 1.0) > 1e-9:
            raise ValueError("location_mix weights must sum to 1")
        return self


class FleetConfig(StrictModel):
    fleet_size: Annotated[int, Field(ge=0, le=1_000_000)] = 100
    charger_kw: FinitePositive = 7.4
    energy_kwh: FinitePositive = 14.0
    efficiency: Annotated[float, Field(gt=0, le=1, allow_inf_nan=False)] = 0.9
    location_mix: LocationMix = Field(default_factory=LocationMix)
    district_mix: dict[str, FinitePositive] | None = None

    @field_validator('district_mix')
    @classmethod
    def district_weights(cls, value):
        if value is not None and (not value or abs(sum(value.values())-1)>1e-9):
            raise ValueError('district_mix must be nonempty positive fractions summing to 1')
        return value


class DistrictOverride(StrictModel):
    capacity_kw: FinitePositive
    provenance: str = Field(min_length=1)

    @field_validator('provenance')
    @classmethod
    def nonblank(cls,value):
        if not value.strip(): raise ValueError('provenance must not be blank')
        return value.strip()


class DistrictCapacity(StrictModel):
    scenario: Literal['low','central','high'] = 'central'
    overrides: dict[str,DistrictOverride] = Field(default_factory=dict)


class NetworkCapacity(StrictModel):
    # Explicit study assumptions; the source image supplies no demand split.
    lv_baseline_fraction: FiniteFraction = 0.5
    lv_ev_fraction: FiniteFraction = 1.0


HardMetric = Literal[
    "min_voltage_pu", "max_line_loading_percent", "max_transformer_loading_percent",
    "unmet_energy_kwh", "nonconverged_steps", "overload_steps", "max_district_loading_percent", "district_overload_steps",
    "max_network_capacity_loading_percent", "network_capacity_overload_steps",
    "energy_excess_kwh", "energy_limit_exceeded_steps",
]


class HardAssertion(StrictModel):
    type: Literal["hard"] = "hard"
    metric: HardMetric
    operator: Literal["le", "ge"]
    value: Annotated[float, Field(allow_inf_nan=False)]


class PairedAssertion(StrictModel):
    type: Literal["paired"] = "paired"
    metric: Literal["peak_demand_kw"]
    reduction_fraction: FiniteFraction
    control: str = Field(min_length=1)
    candidate: str = Field(min_length=1)


Assertion = HardAssertion | PairedAssertion


class Limits(StrictModel):
    min_voltage_pu: Annotated[float, Field(gt=0, le=2, allow_inf_nan=False)] = 0.95
    max_voltage_pu: Annotated[float, Field(gt=0, le=2, allow_inf_nan=False)] = 1.05
    max_loading_percent: FinitePositive = 100.0

    @model_validator(mode="after")
    def voltage_order(self) -> "Limits":
        if self.min_voltage_pu >= self.max_voltage_pu:
            raise ValueError("min_voltage_pu must be less than max_voltage_pu")
        return self


class RewardWeights(StrictModel):
    delivery: Annotated[float, Field(ge=0, le=1e6, allow_inf_nan=False)] = 1.0
    shortfall: Annotated[float, Field(ge=0, le=1e6, allow_inf_nan=False)] = 10.0
    capacity: Annotated[float, Field(gt=0, le=1e6, allow_inf_nan=False)] = 1000.0
    energy: Annotated[float, Field(gt=0, le=1e6, allow_inf_nan=False)] = 1000.0
    switching: Annotated[float, Field(ge=0, le=1e6, allow_inf_nan=False)] = 0.05
    peak: Annotated[float, Field(ge=0, le=1e6, allow_inf_nan=False)] = 0.1
    intervention: Annotated[float, Field(ge=0, le=1e6, allow_inf_nan=False)] = 10.0


class RLControl(StrictModel):
    model_id: str = Field(pattern=r'^model-[a-f0-9]{20}$')
    reward: RewardWeights = Field(default_factory=RewardWeights)
    safety_shield: bool = True
    daily_energy_limit_kwh: FinitePositive | None = None


class TrainingConfig(StrictModel):
    episodes: Annotated[int, Field(ge=1, le=1000)] = 20
    seed: Annotated[int, Field(ge=0, le=2**32-1001)] = 10000
    learning_rate: Annotated[float, Field(gt=0, le=0.1, allow_inf_nan=False)] = 0.01
    gamma: Annotated[float, Field(gt=0, le=1, allow_inf_nan=False)] = 0.99
    max_runtime_seconds: Annotated[float, Field(gt=0, le=86400, allow_inf_nan=False)] = 600
    reward: RewardWeights = Field(default_factory=RewardWeights)
    safety_shield: bool = True
    daily_energy_limit_kwh: FinitePositive | None = None
    demand_scale_min: Annotated[float, Field(gt=0, le=3, allow_inf_nan=False)] = 0.8
    demand_scale_max: Annotated[float, Field(gt=0, le=3, allow_inf_nan=False)] = 1.2
    shape_noise: Annotated[float, Field(ge=0, le=0.5, allow_inf_nan=False)] = 0.1

    @model_validator(mode='after')
    def ordered_scales(self):
        if self.demand_scale_min > self.demand_scale_max:
            raise ValueError('demand_scale_min must not exceed demand_scale_max')
        return self


class Experiment(StrictModel):
    schema_version: Literal[1] = 1
    name: str = Field(min_length=1)
    hypothesis: str = Field(min_length=1)
    metric_boundary: Literal["city_total", "grid_asset", "departure"] = "city_total"
    observation_contract: Literal["current_state"] = "current_state"
    case_origin: Literal["manual", "llm", "random", "ga"] = "manual"
    assumptions: list[str] = Field(default_factory=lambda: [
        "Demand shapes are user-supplied seasonal hourly profiles.",
        "Land-use and charging-window archetypes are explicit planning assumptions.",
    ])
    demand: DemandConfig = Field(default_factory=DemandConfig)
    fleet: FleetConfig = Field(default_factory=FleetConfig)
    district_capacity: DistrictCapacity = Field(default_factory=DistrictCapacity)
    network_capacity: NetworkCapacity = Field(default_factory=NetworkCapacity)
    rl: RLControl | None = None
    strategy_options: StrategyOptions = Field(default_factory=StrategyOptions)
    strategies: list[Literal["immediate", "fixed_delay", "randomized_delay", "capacity_aware", "rl", "least_laxity_first", "valley_filling", "mpc", "voltage_responsive"]] = Field(
        default_factory=lambda: ["immediate", "fixed_delay", "randomized_delay", "capacity_aware"]
    )
    seeds: list[Annotated[int, Field(ge=0, le=2**32 - 1)]] = Field(default_factory=lambda: [1])
    fleet_sizes: list[Annotated[int, Field(ge=0, le=1_000_000)]] | None = None
    limits: Limits = Field(default_factory=Limits)
    assertions: list[Assertion] = Field(default_factory=list)
    max_cases: Annotated[int, Field(ge=1, le=10_000)] = 100
    max_runtime_seconds: Annotated[float, Field(gt=0, le=86_400, allow_inf_nan=False)] = 600.0
    stress_first: bool = True
    stop_on_violation: bool = True
    fixed_start_hour: Annotated[int, Field(ge=0, le=23)] = 23

    @field_validator("strategies", "seeds")
    @classmethod
    def nonempty_unique(cls, value: list[object]) -> list[object]:
        if not value:
            raise ValueError("list must not be empty")
        if len(value) != len(set(value)):
            raise ValueError("list entries must be unique")
        return value

    @field_validator("assumptions")
    @classmethod
    def assumptions_are_labeled(cls, value: list[str]) -> list[str]:
        if not value or any(not item.strip() for item in value):
            raise ValueError("assumptions must contain nonempty labeled entries")
        return value

    @field_validator("fleet_sizes")
    @classmethod
    def unique_sweep(cls, value: list[int] | None) -> list[int] | None:
        if value is not None and (not value or len(value) != len(set(value))):
            raise ValueError("fleet_sizes must be nonempty and unique when supplied")
        return value

    @model_validator(mode="after")
    def paired_assertions_reference_cases(self) -> "Experiment":
        if 'rl' in self.strategies and self.rl is None:
            raise ValueError('Select a trained RL model when using the rl strategy')
        for assertion in self.assertions:
            if isinstance(assertion, PairedAssertion):
                if assertion.control == assertion.candidate:
                    raise ValueError("paired assertion control and candidate must differ")
                if assertion.control not in self.strategies or assertion.candidate not in self.strategies:
                    raise ValueError("paired assertion control and candidate must be selected strategies")
        return self


def load_experiment(source: Mapping[str, object] | str) -> Experiment:
    """Validate a mapping or a YAML document as an :class:`Experiment`."""
    if isinstance(source, str):
        data = yaml.safe_load(source)
    elif isinstance(source, Mapping):
        data = dict(source)
    else:
        raise TypeError("experiment source must be a mapping or YAML string")
    if not isinstance(data, dict):
        raise ValueError("experiment YAML must contain a mapping at its root")
    return Experiment.model_validate(data)


ASSERTION_ADAPTER = TypeAdapter(Assertion)

service.py:
"""Persistent, immutable experiment definitions and restartable local jobs."""
from __future__ import annotations

import hashlib
import itertools
import json
import os
from pathlib import Path
import subprocess
import sys
import time
import uuid
from datetime import datetime, timezone
from typing import Any

from mvgrid.paths import REPOSITORY_ROOT, NOVI_SAD_GENERATED_DIR
from .schema import Experiment, load_experiment


def canonical(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False)


def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_suffix(f".{uuid.uuid4().hex}.tmp")
    temporary.write_text(canonical(value), encoding="utf-8")
    # Windows readers/antivirus may briefly hold a destination without delete sharing.
    for attempt in range(40):
        try:
            os.replace(temporary, path)
            break
        except PermissionError:
            if attempt == 39:
                temporary.unlink(missing_ok=True)
                raise
            time.sleep(.025)


def read_json(path: Path) -> Any:
    # Windows replacement/antivirus sharing locks can briefly deny a read of an
    # otherwise valid atomic state file. Retry only that transient error; missing
    # files and malformed JSON must still surface to callers.
    for attempt in range(40):
        try:
            return json.loads(path.read_text(encoding="utf-8"))
        except PermissionError:
            if attempt == 39: raise
            time.sleep(.025)


def implementation_fingerprint() -> dict:
    import importlib.metadata
    files = {p.name: hashlib.sha256(p.read_bytes()).hexdigest()
             for p in sorted(Path(__file__).parent.glob("*.py"))}
    inputs = {}
    for name in ("novi_sad_synthetic_transformers.csv", "novi_sad_synthetic_feeder_assignments.csv", "novi_sad_seeded_substations.json"):
        p = NOVI_SAD_GENERATED_DIR / name
        inputs[name] = hashlib.sha256(p.read_bytes()).hexdigest()
    topology = REPOSITORY_ROOT / "data/novi_sad/playground/reduced_network.json"
    inputs["reduced_network.json"] = hashlib.sha256(topology.read_bytes()).hexdigest()
    versions = {name: importlib.metadata.version(name) for name in ("pandapower", "numpy", "pandas", "pydantic", "mcp", "scipy")}
    return {"source_hashes": files, "input_hashes": inputs, "dependencies": versions}


def cases_for(config: dict) -> list[dict]:
    sizes = config.get("fleet_sizes") or [config["fleet"]["fleet_size"]]
    return [{"case_id": f"case-{i:04d}", "strategy": strategy, "seed": seed, "fleet_size": size}
            for i, (size, seed, strategy) in enumerate(itertools.product(sizes, config["seeds"], config["strategies"]))]


class Service:
    def __init__(self, root: str | Path | None = None):
        self.root = Path(root or os.environ.get("EV_PLAYGROUND_HOME", REPOSITORY_ROOT / "artifacts" / "playground" / "runtime")).resolve()

    def _path(self, category: str, identifier: str) -> Path:
        if not identifier or any(c not in "abcdefghijklmnopqrstuvwxyz0123456789-" for c in identifier):
            raise ValueError("Invalid identifier; use an ID returned by the service.")
        return self.root / category / identifier

    def catalog(self) -> dict:
        from .network import build_network
        from .districts import resolve_districts
        from .strategies import strategy_catalog
        net,blocks=build_network()
        return {"schema": Experiment.model_json_schema(), "example": Experiment(name="Evening charging comparison", hypothesis="Staggering charging reduces the synchronized evening peak").model_dump(mode="json"),
                "districts":resolve_districts(blocks),
                "capacity_alignment":net.get('capacity_alignment'),
                "excluded_sources":net.get('excluded_sources',[]),
                "excluded_hubs":net.get('excluded_hubs',[]),
                "retained_demand_fraction":net.get('retained_demand_fraction',1.),
                "strategies": [row['id'] for row in strategy_catalog()],"strategy_catalog":strategy_catalog(),
                "backend": "reduced_pandapower", "fidelity": "Balanced equivalent MV network; synthetic blocks, not an as-built model",
                "metrics": ["peak_demand_kw", "max_line_loading_percent", "max_transformer_loading_percent", "min_voltage_pu", "unmet_energy_kwh", "nonconverged_steps", "overload_steps", "max_district_loading_percent", "district_overload_steps", "max_network_capacity_loading_percent", "network_capacity_overload_steps", "energy_excess_kwh", "energy_limit_exceeded_steps"],
                "assumptions": ["15-minute average demand; no sub-interval transients", "Synthetic EV sessions and block allocation", "Selected detailed checks are optional", "Configured limit stop is an experiment stop, not a physical protection-trip model", "City-total demand is scaled by the network retained-demand fraction; the six-source model preserves all city demand by reassigning NS1, NS6 and FUT feeder demand", "All supplied capacity figures accounted for: MV equivalents plus aggregate transmission/downstream constraints; 1178 MW is the infrastructure sum, not a supply limit", "No harmonics or phase imbalance model"]}

    def validate_experiment(self, definition: dict | str) -> dict:
        config = load_experiment(definition).model_dump(mode="json")
        if 'rl' in config['strategies']:
            from .rl_service import RLService
            model = RLService(self.root).get_model(config['rl']['model_id'])
            if set(config['seeds']) & set(model['payload']['training_seeds']):
                raise ValueError('Evaluation seeds overlap the selected model training seeds; choose held-out seeds.')
        from .network import build_network
        from .districts import resolve_districts, validate_district_mix, validate_district_locations
        _,blocks=build_network()
        resolved_districts=resolve_districts(blocks,config['district_capacity'])
        validate_district_mix(blocks,config['fleet'].get('district_mix'))
        validate_district_locations(blocks,config['fleet'])
        cases = cases_for(config)
        if len(cases) > config["max_cases"]:
            raise ValueError(f"Expanded {len(cases)} cases exceeds max_cases={config['max_cases']}")
        replay_events = sum(config["demand"]["days"] * size for size in set(c["fleet_size"] for c in cases)) * len(config["seeds"])
        if replay_events > 250_000:
            raise ValueError("Expanded session replay exceeds the MVP limit of 250,000 events. Reduce fleet sizes, days or seeds.")
        return {"valid": True, "definition": config, "cases": cases,"resolved_districts":resolved_districts,
                "estimated_power_flows": len(cases) * (config["demand"]["days"] * 96 + (36 if any(c['fleet_size'] for c in cases) else 0)),
                "runtime_note": "Upper-bound interval count includes up to 9 hours overnight completion, excludes control retries. Measure runtime on this machine."}

    def save_experiment(self, definition: dict | str) -> dict:
        config = self.validate_experiment(definition)["definition"]
        identifier = "exp-" + digest(config)[:20]
        path = self._path("experiments", identifier).with_suffix(".json")
        record = {"experiment_id": identifier, "definition": config}
        if not path.exists():
            write_json(path, record)
        return record

    def add_cases(self, experiment_id: str, patch: dict) -> dict:
        config = self.get_experiment(experiment_id)["definition"]
        # A patch is a complete replacement for each supplied top-level field.
        config.update(patch)
        return self.save_experiment(config)

    def get_experiment(self, experiment_id: str) -> dict:
        return read_json(self._path("experiments", experiment_id).with_suffix(".json"))

    def list_experiments(self) -> list[dict]:
        return [read_json(p) for p in sorted((self.root / "experiments").glob("*.json"))]

    def list_runs(self) -> list[dict]:
        return [self.get_run(p.parent.name) for p in sorted((self.root / "runs").glob("*/state.json"), reverse=True)
                if not self._run_metadata(p.parent.name).get("deleted_at")]

    def _run_metadata(self, run_id: str) -> dict:
        path = self._path("runs", run_id) / "metadata.json"
        return read_json(path) if path.exists() else {}

    def rename_run(self, run_id: str, name: str) -> dict:
        if not isinstance(name, str) or not 1 <= len(name.strip()) <= 120:
            raise ValueError("Run name must contain 1 to 120 characters.")
        self.get_run(run_id)
        metadata = self._run_metadata(run_id)
        metadata["name"] = name.strip()
        write_json(self._path("runs", run_id) / "metadata.json", metadata)
        return self.get_run(run_id)

    def delete_run(self, run_id: str) -> dict:
        state = self.get_run(run_id)
        if state["status"] in ("starting", "running"):
            raise ValueError("Cancel the active run and wait for it to stop before deleting it.")
        metadata = self._run_metadata(run_id)
        metadata["deleted_at"] = datetime.now(timezone.utc).isoformat()
        write_json(self._path("runs", run_id) / "metadata.json", metadata)
        return {"run_id": run_id, "deleted": True}

    def restore_run(self, run_id: str) -> dict:
        folder = self._path("runs", run_id)
        read_json(folder / "state.json")
        metadata = self._run_metadata(run_id)
        metadata.pop("deleted_at", None)
        write_json(folder / "metadata.json", metadata)
        return self.get_run(run_id)

    def start_run(self, experiment_id: str, resume_run_id: str | None = None) -> dict:
        # CLI children are reclaimed when Codex exits. The GUI process owns jobs
        # started from chat so they survive independently of that CLI invocation.
        broker = os.environ.get("EV_PLAYGROUND_BROKER_URL")
        if broker:
            from urllib.parse import urlsplit
            from urllib.request import Request, urlopen
            from urllib.error import HTTPError
            parsed = urlsplit(broker)
            if parsed.scheme != "http" or parsed.hostname not in ("127.0.0.1", "localhost") or parsed.path not in ("", "/"):
                raise ValueError("The run broker must be a loopback HTTP origin.")
            body = canonical({"experiment_id":experiment_id,"resume_run_id":resume_run_id,"runtime_root":str(self.root)}).encode()
            try:
                with urlopen(Request(broker.rstrip("/")+"/api/runs",data=body,headers={"Content-Type":"application/json"}),timeout=30) as response:
                    return json.load(response)
            except HTTPError as error:
                raise ValueError(json.loads(error.read()).get("error", "Run broker rejected the request")) from error
        self.validate_experiment(self.get_experiment(experiment_id)['definition'])
        self.root.mkdir(parents=True, exist_ok=True)
        lock = self.root / "worker.lock"
        try:
            fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            active = lock.read_text(encoding="utf-8").strip()
            if not active:
                raise ValueError("Another run is being registered; retry shortly.")
            if self.get_run(active)["status"] in ("running", "starting"):
                raise ValueError(f"One worker is active: {active}. Wait or cancel it first.")
            lock.unlink(missing_ok=True)
            fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        try:
            if resume_run_id:
                run_id = resume_run_id
                folder = self._path("runs", run_id)
                state = self.get_run(run_id)
                if state["experiment_id"] != experiment_id or state["status"] not in ("cancelled", "budget_exceeded", "interrupted", "failed"):
                    raise ValueError("Only an interrupted, cancelled, failed or budget-limited matching run can resume.")
                manifest = read_json(folder / "manifest.json")
                if manifest["fingerprint"] != implementation_fingerprint():
                    raise ValueError("Code, dependencies or reference inputs changed; start a new run instead of mixing evidence.")
                if hashlib.sha256((folder / "network.json").read_bytes()).hexdigest() != manifest["network_hash"] or any(digest(replay)!=manifest["replay_hashes"][key] for key,replay in manifest["replays"].items()):
                    raise ValueError("Frozen network or replay changed; cannot resume altered evidence.")
                if any(digest(profile)!=manifest.get('demand_hashes',{}).get(seed) for seed,profile in manifest.get('demand_by_seed',{}).items()):
                    raise ValueError('Frozen randomized demand changed; cannot resume altered evidence.')
                model = manifest.get('rl_model')
                if model and 'model-'+digest(model['payload'])[:20]!=model['model_id']:
                    raise ValueError('Frozen RL policy changed; cannot resume altered evidence.')
                (folder / "cancel").unlink(missing_ok=True)
            else:
                run_id = "run-" + uuid.uuid4().hex[:16]
                folder = self._path("runs", run_id)
                folder.mkdir(parents=True)
                state = {"run_id": run_id, "experiment_id": experiment_id, "status": "starting", "completed_cases": 0,
                         "created_at": datetime.now(timezone.utc).isoformat(), "verdict": "incomplete"}
                write_json(folder / "state.json", state)
            os.write(fd, run_id.encode())
            os.close(fd)
            fd = None
            state.update(status="starting", verdict="incomplete", pid=None)
            write_json(folder / "state.json", state)
            env = dict(os.environ, PYTHONPATH=str(REPOSITORY_ROOT / "src"))
            log = open(folder / "worker.log", "a", encoding="utf-8")
            try:
                process = subprocess.Popen([sys.executable, "-m", "mvgrid.novi_sad.playground.worker", str(self.root), run_id],
                    cwd=str(REPOSITORY_ROOT), env=env, stdout=log, stderr=log,
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            finally:
                log.close()
            # Worker waits for pid registration to avoid competing state writes.
            state["pid"] = process.pid
            write_json(folder / "state.json", state)
            return state
        except Exception:
            if fd is not None:
                os.close(fd)
            lock.unlink(missing_ok=True)
            raise

    def get_run(self, run_id: str) -> dict:
        if run_id.startswith('train-'):
            from .rl_service import RLService
            return RLService(self.root).get_job(run_id)
        folder = self._path("runs", run_id)
        metadata = self._run_metadata(run_id)
        if metadata.get("deleted_at"):
            raise FileNotFoundError("Run has been deleted. Restore it before opening its evidence.")
        state = read_json(folder / "state.json")
        pid = state.get("pid")
        if state["status"] in ("running", "starting") and pid:
            import psutil
            if not psutil.pid_exists(pid):
                state.update(status="interrupted", verdict="incomplete")
                write_json(folder / "state.json", state)
        elif state["status"] == "starting" and not pid:
            if time.time() - (folder / "state.json").stat().st_mtime > 30:
                state.update(status="interrupted", verdict="incomplete")
                write_json(folder / "state.json", state)
        return {**state, "name": metadata.get("name", run_id)}

    def cancel_run(self, run_id: str) -> dict:
        state = self.get_run(run_id)
        if state["status"] in ("starting", "running"):
            (self._path("runs", run_id) / "cancel").touch()
        return {"run_id": run_id, "cancel_requested": state["status"] in ("starting", "running")}

    def get_results(self, run_id: str, case_id: str | None = None) -> dict:
        folder = self._path("runs", run_id)
        state = self.get_run(run_id)
        files = sorted((folder / "cases").glob("*.json"))
        if case_id:
            files = [p for p in files if p.stem == case_id]
            if not files:
                raise ValueError("Case not found among completed results; inspect run progress and returned case IDs.")
        return {"run": state, "cases": [read_json(p) for p in files],
                "evaluation": read_json(folder / "evaluation.json") if (folder / "evaluation.json").exists() else None}

    def compare_runs(self, run_ids: list[str]) -> dict:
        if len(run_ids) < 2 or len(run_ids) > 8:
            raise ValueError("Compare between two and eight runs.")
        rows, definitions, fingerprints, coverage = [], [], [], []
        for run_id in run_ids:
            result = self.get_results(run_id)
            coverage.append(bool(result["run"]["status"] == "completed" and result.get("evaluation") and result["evaluation"].get("complete") and all(case.get("complete", True) for case in result["cases"])))
            definitions.append(self.get_experiment(result["run"]["experiment_id"])["definition"])
            manifest = self._path("runs", run_id) / "manifest.json"
            fingerprints.append(read_json(manifest).get("fingerprint") if manifest.exists() else None)
            rows.extend({"run_id": run_id, "case_id": c["case_id"], "strategy": c["strategy"], "seed": c["seed"], "fleet_size": c["fleet_size"], "metrics": c["metrics"], "complete": c.get("complete", True), "run_status": result["run"]["status"]} for c in result["cases"])
        differing = [key for key in sorted(set().union(*(d.keys() for d in definitions))) if any(d.get(key) != definitions[0].get(key) for d in definitions[1:])]
        energy_budgets_match = all((d.get('rl') or {}).get('daily_energy_limit_kwh') == (definitions[0].get('rl') or {}).get('daily_energy_limit_kwh') for d in definitions)
        return {"rows": rows, "differing_fields": differing,
                "complete": all(coverage),
                "paired_compatible": all(coverage) and energy_budgets_match and all(f == fingerprints[0] and f is not None for f in fingerprints) and not any(k in differing for k in ("demand", "fleet", "seeds", "fleet_sizes", "limits", "district_capacity", "network_capacity", "fixed_start_hour", "stop_on_violation", "strategy_options")),
                "note": "Paired compatibility requires completed runs with full case coverage and matching inputs. Stopped prefixes are descriptive only. Compare matched seeds and fleet sizes; changes to assumptions are not pure controller effects."}

simulation.py:
"""Chronological 15-minute EV simulation with a fresh pandapower network per case."""
from __future__ import annotations
import copy
import math
import random
import time
import pandapower as pp
from pandapower.powerflow import LoadflowNotConverged
from .network import build_network
from .districts import district_id as get_district_id, resolve_districts
from .capacity_layers import capacity_layers, ev_stage_fraction
from .schema import NetworkCapacity
from .strategies import NEW_STRATEGIES, create_controller


class Simulator:
    """Small reset/step interface usable by future optimizer and RL adapters."""
    def reset(self, case, demand_kw, sessions):
        self.case = copy.deepcopy(case)
        self.net, self.blocks = (pp.from_json(case['network_path']),copy.deepcopy(case['blocks'])) if case.get('network_path') else build_network()
        self.by_id = {b['id']:b for b in self.blocks}
        self.resolved_districts=copy.deepcopy(case.get('resolved_districts')) if case.get('resolved_districts') is not None else resolve_districts(self.blocks,case.get('district_capacity'))
        self.district_by_id={d['id']:d for d in self.resolved_districts}
        for b in self.blocks:
            if get_district_id(b) not in self.district_by_id: raise ValueError('Frozen districts do not cover network blocks')
        self.demand = list(demand_kw)
        self.dt = float(case.get('dt_hours',.25))
        if self.dt <= 0: raise ValueError('dt_hours must be positive')
        if any(not math.isfinite(v) or v < 0 for v in self.demand): raise ValueError('Demand must be finite and nonnegative')
        self.sessions = copy.deepcopy(sessions)
        rng = random.Random(case.get('seed',0))
        ids = set()
        for s in sorted(self.sessions,key=lambda x:str(x['id'])):
            if s['id'] in ids: raise ValueError('Duplicate session ID')
            ids.add(s['id'])
            if s['block_id'] not in self.by_id: raise ValueError('Unknown session block')
            s['district_id']=get_district_id(self.by_id[s['block_id']])
            if not (0 <= s['arrival_step'] < s['departure_step']): raise ValueError('Invalid session window')
            if s['energy_kwh'] < 0 or s['charger_kw'] <= 0 or not 0 < s.get('efficiency',.9) <= 1: raise ValueError('Invalid energy, charger or efficiency')
            s['remaining_kwh'] = float(s['energy_kwh'])
            s['delivered_kwh'] = 0.
            s['delay_jitter'] = rng.randrange(max(1,int(4/self.dt)))
        self.stopped = False
        self.index = 0
        self.intervals = []
        self.daily_energy_kwh = 0.
        self.energy_day = None
        return self.observation()

    def observation(self):
        return {'step':self.index,'baseline_kw':self.demand[self.index] if self.index<len(self.demand) else None,'sessions':[{k:v for k,v in s.items() if k!='delay_jitter'} for s in self.sessions if s['arrival_step']<=self.index<s['departure_step']],'done':self.stopped or self.index>=len(self.demand)}

    def step(self, charging_actions=None):
        if self.stopped or self.index >= len(self.demand): raise RuntimeError('Simulation finished')
        t = self.index
        baseline = {b['id']:float(self.case['block_demand_kw'][b['id']][t]) if self.case.get('block_demand_kw') else self.demand[t]*b['base_weight'] for b in self.blocks}
        loading_factor = self.case.get('limits',{}).get('max_loading_percent',100)/100
        strategy = self.case.get('strategy','immediate')
        if strategy not in ('immediate','fixed_delay','randomized_delay','capacity_aware','rl',*NEW_STRATEGIES): raise ValueError('Unknown strategy')
        if strategy in ('rl',*NEW_STRATEGIES) and charging_actions is None: raise ValueError(f'{strategy} strategy requires a loaded controller')
        connected = [s for s in self.sessions if s['arrival_step']<=t<s['departure_step']]
        source_remaining = {}
        block_remaining = {}
        district_remaining={d['id']:d['capacity_kw'] for d in self.resolved_districts}
        stage_remaining={r['id']:r['headroom_kw'] for r in capacity_layers(self.net, self.blocks, baseline, {b['id']:0. for b in self.blocks}, self.case.get('network_capacity'))}
        for b in self.blocks:
            source_remaining.setdefault(b['source_id'],b['source_capacity_kw']*loading_factor)
            source_remaining[b['source_id']] -= baseline[b['id']]
            block_remaining[b['id']] = max(0,b['capacity_kw']*loading_factor-baseline[b['id']])
            district_remaining[get_district_id(b)]-=baseline[b['id']]
        allocations = {}
        requested_power = {}
        for s in sorted(connected,key=lambda x:(x['departure_step'],str(x['id']))):
            power = min(s['charger_kw'],s['remaining_kwh']/(self.dt*s.get('efficiency',.9)))
            if charging_actions is not None:
                requested = float(charging_actions.get(s['id'],0))
                if not math.isfinite(requested) or requested<0: raise ValueError('Invalid charging action')
                power = min(power,requested)
            elif strategy in ('fixed_delay','randomized_delay'):
                day_steps = int(round(24/self.dt))
                start = (s['arrival_step']//day_steps)*day_steps + int(self.case.get('fixed_start_hour',23)/self.dt)
                # Arrivals after scheduled start charge immediately; early arrivals wait.
                if strategy == 'randomized_delay': start += s['delay_jitter']
                if t<max(s['arrival_step'],start): power = 0.
            requested_power[s['id']] = power
            if (strategy=='capacity_aware' and charging_actions is None) or strategy=='voltage_responsive':
                b = self.by_id[s['block_id']]
                power = min(power,block_remaining[b['id']],max(0,source_remaining[b['source_id']]),max(0,district_remaining[get_district_id(b)]))
                for stage, remaining in stage_remaining.items():
                    share=ev_stage_fraction(stage,b,self.case.get('network_capacity'))
                    if share: power=min(power,max(0,remaining)/share)
                for stage in stage_remaining:
                    stage_remaining[stage]-=power*ev_stage_fraction(stage,b,self.case.get('network_capacity'))
                block_remaining[b['id']] -= power
                source_remaining[b['source_id']] -= power
                district_remaining[get_district_id(b)]-=power
            allocations[s['id']] = max(0,power)
        ev = {b['id']:0. for b in self.blocks}
        for s in connected: ev[s['block_id']] += allocations[s['id']]
        for b in self.blocks:
            p = (baseline[b['id']]+ev[b['id']])/1000
            self.net.load.loc[b['load_index'],['p_mw','q_mvar']] = [p,p*math.tan(math.acos(.97))]
        converged = True
        try:
            pp.runpp(self.net,numba=False,init='results' if t and self.net.converged else 'auto',max_iteration=int(self.case.get('max_iteration',30)))
        except LoadflowNotConverged:
            converged = False
        limits = {'min_voltage_pu':.95,'max_voltage_pu':1.05,'max_loading_percent':100,**self.case.get('limits',{})}
        safety_iterations = 0
        def stage_states():
            rows=capacity_layers(self.net,self.blocks,baseline,ev,self.case.get('network_capacity'),
                float(self.net.res_ext_grid.p_mw.sum())*1000 if converged else None)
            if not converged:
                for row in rows:
                    if row['id']=='transmission':
                        row.update(demand_kw=None,headroom_kw=None,installed_headroom_kw=None,loading_percent=None,installed_loading_percent=None,reserve_used_kw=None,reserve_remaining_kw=None,capacity_exceeded=False)
            return rows
        def electrically_safe():
            return converged and self.net.res_bus.vm_pu.min() >= limits['min_voltage_pu'] and self.net.res_bus.vm_pu.max() <= limits['max_voltage_pu'] and self.net.res_line.loading_percent.max() <= limits['max_loading_percent'] and self.net.res_trafo.loading_percent.max() <= limits['max_loading_percent'] and not any(r['capacity_exceeded'] for r in stage_states())
        if (strategy == 'capacity_aware' and charging_actions is None) or strategy in NEW_STRATEGIES or (strategy == 'rl' and (self.case.get('rl') or {}).get('safety_shield',True)):
            # Bounded conservative AC safety wrapper. Last attempt removes all EV power;
            # residual violations then belong to the baseline, never hidden by clipping.
            while not electrically_safe() and sum(allocations.values()) > 1e-9 and safety_iterations < 8:
                safety_iterations += 1
                factor = 0. if safety_iterations == 8 else .5
                if strategy == 'rl':
                    # Preserve binary commands: remove complete charger allocations,
                    # keeping the nearest departures, rather than halve their power.
                    active = [s['id'] for s in sorted(connected,key=lambda s:(s['departure_step'],str(s['id']))) if allocations[s['id']]>1e-9]
                    keep = set(active[:len(active)//2]) if factor else set()
                    allocations = {key:value if key in keep else 0. for key,value in allocations.items()}
                else:
                    allocations = {key:value*factor for key,value in allocations.items()}
                ev = {b['id']:0. for b in self.blocks}
                for session in connected: ev[session['block_id']] += allocations[session['id']]
                for block in self.blocks:
                    p = (baseline[block['id']]+ev[block['id']])/1000
                    self.net.load.loc[block['load_index'],['p_mw','q_mvar']] = [p,p*math.tan(math.acos(.97))]
                try:
                    pp.runpp(self.net,numba=False,init='auto',max_iteration=int(self.case.get('max_iteration',30)))
                    converged = True
                except LoadflowNotConverged:
                    converged = False
        violations = []
        snapshots = []
        # EV energy is requested consumption even if a steady-state solution fails; no protection model is implied.
        for s in connected:
            delivered = allocations[s['id']]*self.dt*s.get('efficiency',.9)
            s['remaining_kwh'] = max(0,s['remaining_kwh']-delivered)
            s['delivered_kwh'] += delivered
        for b in self.blocks:
            voltage = float(self.net.res_bus.at[b['bus_index'],'vm_pu']) if converged else None
            line_indices = list(dict.fromkeys([b['line_index'], *b.get('upstream_line_indices',[])]))
            trafo_indices = list(dict.fromkeys([b['trafo_index'], *b.get('upstream_trafo_indices',[])]))
            line = max(float(self.net.res_line.at[i,'loading_percent']) for i in line_indices) if converged else None
            trafo = max(float(self.net.res_trafo.at[i,'loading_percent']) for i in trafo_indices) if converged else None
            vehicles=[]
            counts=dict(connected=0,charging=0,waiting=0,completed=0,departed_shortfall=sum(s['block_id']==b['id'] and s['departure_step']<=t+1 and s['remaining_kwh']>1e-6 for s in self.sessions))
            for s in connected:
                if s['block_id']!=b['id']: continue
                status = 'charging' if allocations[s['id']]>1e-9 else 'completed' if s['remaining_kwh']<=1e-6 else 'waiting'
                counts['connected']+=1
                counts[status]+=1
                vehicles.append(dict(id=s['id'],district_id=s['district_id'],status=status,power_kw=allocations[s['id']],remaining_kwh=s['remaining_kwh']))
            snapshots.append(dict(id=b['id'],baseline_kw=baseline[b['id']],ev_kw=ev[b['id']],total_kw=baseline[b['id']]+ev[b['id']],voltage_pu=voltage,line_loading_percent=line,transformer_loading_percent=trafo,counts=counts,vehicles=vehicles))
        # Check every retained electrical asset, including upstream delivery chains.
        def affected(kind,index):
            if kind=='bus':
                return [b for b in self.blocks if index in [b['bus_index'], *b.get('upstream_bus_indices',b.get('path_bus_indices',[]))]]
            own='line_index' if kind=='line' else 'trafo_index'
            chain='upstream_line_indices' if kind=='line' else 'upstream_trafo_indices'
            return [b for b in self.blocks if index in [b[own], *b.get(chain,[])]]
        if converged:
            for asset_type, table, values, field in [('bus',self.net.bus,self.net.res_bus,'vm_pu'),('line',self.net.line,self.net.res_line,'loading_percent'),('transformer',self.net.trafo,self.net.res_trafo,'loading_percent')]:
                for index,row in table.iterrows():
                    value=float(values.at[index,field])
                    candidates=[('undervoltage',limits['min_voltage_pu'],value<limits['min_voltage_pu']),('overvoltage',limits['max_voltage_pu'],value>limits['max_voltage_pu'])] if asset_type=='bus' else [(asset_type+'_overload',limits['max_loading_percent'],value>limits['max_loading_percent'])]
                    for kind,limit,bad in candidates:
                        if not bad: continue
                        downstream=affected(asset_type,index)
                        for block in downstream or [None]:
                            violations.append(dict(kind=kind,asset_id=str(row['name']),asset_type=asset_type,asset_index=int(index),block_id=block['id'] if block else None,value=value,limit=limit))
        else:
            violations.append(dict(kind='nonconvergence',asset_id='network',value=None,limit=None))
        stages=stage_states()
        for row in stages:
            if row['capacity_exceeded']:
                violations.append(dict(kind='network_capacity_exceeded',asset_type='capacity_stage',asset_id=row['id'],value=row['demand_kw'],limit=row['capacity_kw'],block_ids=row['block_ids']))
        transformers=[]
        for index,row in self.net.trafo.iterrows():
            downstream=affected('transformer',index)
            transformers.append(dict(id=str(row['name']),index=int(index),hv_kv=float(row.vn_hv_kv),lv_kv=float(row.vn_lv_kv),rating_mva=float(row.sn_mva),
                p_mw=float(self.net.res_trafo.at[index,'p_hv_mw']) if converged else None,
                q_mvar=float(self.net.res_trafo.at[index,'q_hv_mvar']) if converged else None,
                loading_percent=float(self.net.res_trafo.at[index,'loading_percent']) if converged else None,
                block_ids=[b['id'] for b in downstream],district_ids=sorted({b.get('delivery_station_id',b.get('delivery_id',b['source_id'])) for b in downstream}),
                has_violation=not converged or any(v.get('asset_type')=='transformer' and v.get('asset_index')==index for v in violations)))
        districts={}
        for block in self.blocks:
            district_id=get_district_id(block)
            district=districts.setdefault(district_id,dict(**self.district_by_id[district_id],baseline_kw=0.,ev_kw=0.,total_kw=0.,has_violation=False,counts=dict(connected=0,charging=0,waiting=0,completed=0,departed_shortfall=0)))
            district['baseline_kw']+=baseline[block['id']]
            district['ev_kw']+=ev[block['id']]
            district['total_kw']+=baseline[block['id']]+ev[block['id']]
            district['has_violation'] |= not converged or any(v.get('block_id')==block['id'] for v in violations)
        for district in districts.values():
            district['headroom_kw']=district['capacity_kw']-district['total_kw']
            district['loading_percent']=district['total_kw']/district['capacity_kw']*100
            exceeded=district['total_kw']>district['capacity_kw']+1e-9
            district['capacity_exceeded']=exceeded
            district['has_violation'] |= exceeded
            if exceeded:
                violations.append(dict(kind='district_capacity_exceeded',asset_type='district',asset_id=district['id'],district_id=district['id'],value=district['total_kw'],limit=district['capacity_kw'],block_ids=district['block_ids']))
            for snapshot in snapshots:
                if snapshot['id'] not in district['block_ids']: continue
                snapshot.update(district_id=district['id'],district_loading_percent=district['loading_percent'],district_capacity_exceeded=exceeded)
                for key,value in snapshot['counts'].items(): district['counts'][key]+=value
        interval=dict(step=t,safety_iterations=safety_iterations,baseline_kw=sum(baseline.values()),requested_ev_kw=sum(requested_power.values()),curtailed_ev_kw=max(0,sum(requested_power.values())-sum(ev.values())),ev_kw=sum(ev.values()),total_kw=sum(baseline.values())+sum(ev.values()),converged=converged,min_voltage_pu=float(self.net.res_bus.vm_pu.min()) if converged else None,max_line_loading_percent=float(self.net.res_line.loading_percent.max()) if converged else None,max_transformer_loading_percent=float(self.net.res_trafo.loading_percent.max()) if converged else None,losses_kw=float((self.net.res_line.pl_mw.sum()+self.net.res_trafo.pl_mw.sum())*1000) if converged else None,violations=violations,blocks=snapshots,transformers=transformers,districts=list(districts.values()))
        day = int(t*self.dt//24)
        if self.energy_day != day: self.energy_day = day; self.daily_energy_kwh = 0.
        energy_before = self.daily_energy_kwh
        self.daily_energy_kwh += interval['total_kw']*self.dt
        energy_limit = (self.case.get('rl') or {}).get('daily_energy_limit_kwh')
        interval.update(daily_energy_kwh=self.daily_energy_kwh,energy_excess_kwh=0.,energy_limit_exceeded=False)
        if energy_limit:
            interval['energy_excess_kwh'] = max(0.,self.daily_energy_kwh-energy_limit)-max(0.,energy_before-energy_limit)
            interval['energy_limit_exceeded'] = self.daily_energy_kwh>energy_limit+1e-9
            if interval['energy_limit_exceeded']:
                violations.append(dict(kind='daily_energy_exceeded',asset_type='energy_budget',asset_id='city_load',value=self.daily_energy_kwh,limit=energy_limit))
        self.intervals.append(interval)
        interval['applied_actions_kw'] = dict(allocations)
        interval['capacity_layers']=stages
        interval['max_network_capacity_loading_percent']=max((r['loading_percent'] for r in stages if r['loading_percent'] is not None),default=None)
        interval['max_district_loading_percent']=max(d['loading_percent'] for d in districts.values())
        self.index += 1
        self.stopped = bool(self.case.get('stop_on_violation',True) and violations)
        return self.observation(),interval,self.stopped or self.index>=len(self.demand)


def simulate_case(case, demand_kw, sessions, on_step=None, controller=None):
    started=time.perf_counter()
    simulator=Simulator()
    simulator.reset(case,demand_kw,sessions)
    if case.get('strategy') in NEW_STRATEGIES and controller is None:
        controller = create_controller(case['strategy'],case.get('strategy_options'))
